use crate::{WorkflowSnapshot,WorkflowMutation,S_WORKFLOW_SCHEMA};
fn laws()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
#[test]
fn sqlite_snapshot_workflow_bare_native_codec_requires_the_complete_semantic_owner(){assert!(store::ArtifactCodec::bare::<WorkflowSnapshot,WorkflowMutation>(S_WORKFLOW_SCHEMA).snapshot_sqlite.is_some(),"Workflow requires its own semantic provider");}
#[test]
fn sqlite_snapshot_workflow_complete_neutral_native_fields_retain_both_declared_encodings(){
 let expected:WorkflowSnapshot=semio_framework_pack_json::from_json_str(&laws()["snapshot"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();assert_eq!(expected.parameters.len(),4);assert_eq!(expected.graph.nodes.len(),2);assert_eq!(expected.graph.edges[0].contract.conversion,Some((crate::MediaForm::Procedure,crate::MediaForm::Deck)));for text in[false,true]{let actual=if text{<WorkflowSnapshot as store::ArtifactDsl>::parse_dsl(&store::ArtifactDsl::print_dsl(&expected)).unwrap()}else{<WorkflowSnapshot as store::ArtifactPack>::decode_pack_with(&store::ArtifactPack::encode_pack_with(&expected,&store::PackEncodeOptions::default()).unwrap(),&store::PackDecodeOptions::default()).unwrap()};assert_eq!(actual,expected);}
}
fn words(value:&WorkflowSnapshot)->Vec<Option<u64>>{let mut words=Vec::new();for node in &value.graph.nodes{words.extend([Some(node.x.to_bits()),Some(node.y.to_bits()),Some(node.width.to_bits()),Some(node.height.to_bits())])}for parameter in &value.parameters{if let crate::WorkflowParameter::Numeric{value,min,max,step,..}=parameter{words.extend([Some(value.to_bits()),min.map(f64::to_bits),max.map(f64::to_bits),step.map(f64::to_bits)])}}words}
#[test]
fn sqlite_snapshot_workflow_all_native_geometry_and_optional_parameter_words_are_exact(){
 for hex in laws()["binary64Words"].as_array().unwrap(){let bits=u64::from_str_radix(hex.as_str().unwrap(),16).unwrap();let number=f64::from_bits(bits);let mut expected:WorkflowSnapshot=semio_framework_pack_json::from_json_str(&laws()["snapshot"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();for node in &mut expected.graph.nodes{node.x=number;node.y=number;node.width=number;node.height=number}for parameter in &mut expected.parameters{if let crate::WorkflowParameter::Numeric{value,min,max,step,..}=parameter{*value=number;*min=Some(number);*max=Some(number);*step=Some(number)}}for text in[false,true]{let actual=if text{<WorkflowSnapshot as store::ArtifactDsl>::parse_dsl(&store::ArtifactDsl::print_dsl(&expected)).unwrap()}else{<WorkflowSnapshot as store::ArtifactPack>::decode_pack_with(&store::ArtifactPack::encode_pack_with(&expected,&store::PackEncodeOptions::default()).unwrap(),&store::PackDecodeOptions::default()).unwrap()};assert_eq!(words(&actual),vec![Some(bits);12],"{hex}: native Text={text}");assert_eq!(actual.graph.edges,expected.graph.edges);assert_eq!(actual.inputs,expected.inputs);assert_eq!(actual.parameter_bindings,expected.parameter_bindings);}}
}

use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteDatabaseLimits,SqliteSnapshotControl,SqliteSnapshotPhase,SqliteSnapshotProgress,SnapshotEncoding,export_sqlite_database,import_sqlite_database}};
fn source()->WorkflowSnapshot{semio_framework_pack_json::from_json_str(&laws()["snapshot"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn database(value:&WorkflowSnapshot)->SqliteDatabase{value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(value:&SqliteDatabase)->WorkflowSnapshot{WorkflowSnapshot::from_sqlite_database(value,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn file(value:&WorkflowSnapshot)->Vec<u8>{export_sqlite_database(&database(value),SqliteDatabaseLimits::default(),&mut |_|true).unwrap()}
fn payload(value:&WorkflowSnapshot,encoding:SnapshotEncoding)->store::io_schema::IoPayload{match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(store::ArtifactPack::encode_pack(value)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(store::ArtifactDsl::print_dsl(value))}}
fn dialect()->semio_framework_artifact_reference::ArtifactDialect{semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"os.workflow".into(),standard:"1".into(),subset:"*".into()}}
fn oracle(script:&str,input:&[u8])->Vec<u8>{use std::{io::Write,process::{Command,Stdio}};let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(input).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));output.stdout}
#[test]
fn sqlite_snapshot_workflow_complete_relational_root_and_empty_collections_restore(){
 let expected=source();let d=database(&expected);assert_eq!(d.tables.iter().map(|t|t.rows.len()).collect::<Vec<_>>(),vec![1,1,2,3,2,2,4,1,1,3,1,1,2,2,2,2]);assert_eq!(restore(&d),expected);
 let mut empty=expected;empty.graph.nodes.clear();empty.graph.edges.clear();empty.parameters.clear();empty.parameter_bindings.clear();empty.inputs.clear();empty.input_bindings.clear();empty.output_bindings.clear();let d=database(&empty);assert_eq!(d.tables.iter().map(|t|t.rows.len()).sum::<usize>(),2);assert_eq!(restore(&d),empty);
}
#[test]
fn sqlite_snapshot_workflow_independent_sql_queries_and_surrogate_edits_preserve_all_fields(){
 let mut expected=source();let script=r#"import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(db.query("SELECT count(*) AS n FROM sqlite_schema WHERE type='table'").get().n!==16n)throw Error('owned table count');const ports=db.query('SELECT endpoint_id,port_id,direction,collection,media_form,kind_id FROM workflow_port ORDER BY id').all();if(ports.length!==3||ports[0].endpoint_id!==''||ports[0].port_id!==''||ports[0].direction!==1n||ports[0].collection!=='input'||ports[0].media_form!==14n||ports[0].kind_id!==''||ports[1].kind_id!==null)throw Error('full independent port query');const edges=db.query('SELECT source_node_id,target_port_id FROM workflow_edge ORDER BY ordinal').all();if(edges[0].source_node_id!=='missing'||edges[0].target_port_id!=='!@/')throw Error('unresolved literal endpoints');const n=db.query('SELECT value,value_bits,min,min_bits,min_class FROM workflow_numeric').get();const word=Buffer.alloc(8);word.writeDoubleBE(1.25);if(n.value_bits!==word.readBigInt64BE()||n.min!==null||n.min_bits!==null||n.min_class!==null)throw Error('optional native binary64');const options=db.query('SELECT value FROM workflow_category_option ORDER BY ordinal').all();if(options.length!==3||options[0].value!==''||options[1].value!==''||options[2].value!=='\0😀')throw Error('ordered duplicate options');db.run('UPDATE workflow_graph SET id=id+90');db.run('UPDATE workflow_node SET graph_id=graph_id+90,id=id+90');db.run('UPDATE workflow_port SET node_id=node_id+90,id=id+90');db.run('UPDATE workflow_edge SET graph_id=graph_id+90,id=id+90');db.run('UPDATE workflow_contract SET edge_id=edge_id+90,id=id+90');db.run('UPDATE workflow_parameter SET id=id+90');for(const table of['workflow_numeric','workflow_categorical','workflow_toggle','workflow_text'])db.run('UPDATE '+table+' SET parameter_id=parameter_id+90,id=id+90');db.run('UPDATE workflow_category_option SET categorical_id=categorical_id+90,id=id+90');for(const table of['workflow_parameter_binding','workflow_input','workflow_input_binding'])db.run('UPDATE '+table+' SET id=id+90');db.run('UPDATE workflow_output_binding SET id=id+90,path_template=?',['edited\0世界']);await Bun.write(Bun.stdout,db.serialize());db.close();"#;
 let edited=oracle(script,&file(&expected));for value in &mut expected.output_bindings{value.path_template="edited\0世界".into()}assert_eq!(restore(&import_sqlite_database(&edited,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()),expected);
}
#[test]
fn sqlite_snapshot_workflow_exact_geometry_and_optional_numeric_words_reach_both_erased_native_directions(){
 let codec=store::ArtifactCodec::bare::<WorkflowSnapshot,WorkflowMutation>(S_WORKFLOW_SCHEMA);let owner=codec.snapshot_sqlite.unwrap();for hex in laws()["binary64Words"].as_array().unwrap(){let bits=u64::from_str_radix(hex.as_str().unwrap(),16).unwrap();let number=f64::from_bits(bits);let mut expected=source();for node in &mut expected.graph.nodes{node.x=number;node.y=number;node.width=number;node.height=number}for parameter in &mut expected.parameters{if let crate::WorkflowParameter::Numeric{value,min,max,step,..}=parameter{*value=number;*min=Some(number);*max=Some(number);*step=Some(number)}}
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let d=(owner.export)(&codec.schema,&dialect(),&payload(&expected,encoding),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let d=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!(words(&restore(&d)),vec![Some(bits);12]);let output=(owner.import)(&codec.schema,&dialect(),d,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let actual=WorkflowSnapshot::decode_sqlite_snapshot_native(&output,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(words(&actual),vec![Some(bits);12]);assert_eq!(actual.graph.edges,expected.graph.edges);assert_eq!(actual.inputs,expected.inputs);assert_eq!(actual.parameter_bindings,expected.parameter_bindings);}
 }
}
#[test]
fn sqlite_snapshot_workflow_every_declared_media_vocabulary_and_optional_literal_kind_restore(){
 let fixture=laws();for(index,form)in fixture["mediaForms"].as_array().unwrap().iter().enumerate(){let mut expected=source();let port=&mut expected.graph.nodes[0].inputs[0];port.spec.media_type.class=crate::media_class_from_ordinal((index%fixture["mediaClasses"].as_array().unwrap().len())as u32).unwrap();port.spec.media_type.form=crate::media_form_from_ordinal(index as u32).unwrap();port.spec.kind_id=if index%2==0{None}else{Some(String::new())};assert_eq!(format!("{:?}",port.spec.media_type.form).to_lowercase(),form.as_str().unwrap().to_lowercase());assert_eq!(restore(&database(&expected)),expected);}
}
#[test]
fn sqlite_snapshot_workflow_independent_malformed_edits_refuse_every_owned_relationship(){
 let script=r#"import{Database}from'bun:sqlite';const input=JSON.parse(await Bun.stdin.text());const results=[];for(const sql of input.sql){const db=Database.deserialize(new Uint8Array(input.bytes));db.run('PRAGMA ignore_check_constraints=ON');db.run(sql);results.push(Array.from(db.serialize()));db.close()}await Bun.write(Bun.stdout,JSON.stringify(results));"#;let fixture=laws();let edited:Vec<Vec<u8>>=serde_json::from_slice(&oracle(script,serde_json::json!({"bytes":file(&source()),"sql":fixture["malformedSql"]}).to_string().as_bytes())).unwrap();assert_eq!(edited.len(),20);for(sql,bytes)in fixture["malformedSql"].as_array().unwrap().iter().zip(edited){assert!(import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).and_then(|d|WorkflowSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))).is_err(),"{sql}")}
}
#[test]
fn sqlite_snapshot_workflow_exact_row_limits_and_tiny_owned_native_frontiers_are_enforced(){
 let expected=source();let d=database(&expected);let limits=SqliteDatabaseLimits::default();assert_eq!(d.tables.iter().map(|t|t.rows.len()).sum::<usize>(),30);assert!(expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:30,..limits})).is_ok());assert!(expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:29,..limits})).is_err());assert!(WorkflowSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:1,..limits})).is_err());for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{for limit in[SqliteDatabaseLimits{max_rows:29,..limits},SqliteDatabaseLimits{max_value_bytes:1,..limits},SqliteDatabaseLimits{max_file_bytes:1,..limits}]{assert!(WorkflowSnapshot::decode_sqlite_snapshot_native(&payload(&expected,encoding),&mut SqliteSnapshotControl::new(&mut |_|true,limit)).is_err());assert!(expected.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limit)).is_err())}}
}
#[test]
fn sqlite_snapshot_workflow_long_literal_unicode_cancellation_reaches_all_four_owned_phases(){
 let mut expected=source();expected.graph.nodes[0].label="😀".repeat(laws()["control"]["largeCharacters"].as_u64().unwrap()as usize);let d=database(&expected);let limits=SqliteDatabaseLimits::default();for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot,SqliteSnapshotPhase::DecodeNative,SqliteSnapshotPhase::EncodeNative]{let mut reached=false;let mut callback=|event:SqliteSnapshotProgress|if event.phase==phase&&event.total>=65536&&event.completed>=65536&&event.completed<event.total{reached=true;false}else{true};let mut control=SqliteSnapshotControl::new(&mut callback,limits);let rejected=match phase{SqliteSnapshotPhase::ProjectSnapshot=>expected.to_sqlite_database(&mut control).is_err(),SqliteSnapshotPhase::ReconstructSnapshot=>WorkflowSnapshot::from_sqlite_database(&d,&mut control).is_err(),SqliteSnapshotPhase::DecodeNative=>WorkflowSnapshot::decode_sqlite_snapshot_native(&payload(&expected,SnapshotEncoding::Text),&mut control).is_err(),SqliteSnapshotPhase::EncodeNative=>expected.encode_sqlite_snapshot_native(SnapshotEncoding::Text,&mut control).is_err(),_=>panic!("unexpected phase")};assert!(rejected,"{phase:?}");assert!(reached,"{phase:?}")}
}
#[test]
fn sqlite_snapshot_workflow_caller_cancellation_reaches_interior_known_node_collections(){
 let mut expected=source();expected.graph.nodes=vec![expected.graph.nodes[0].clone();laws()["control"]["collectionLength"].as_u64().unwrap()as usize];let limits=SqliteDatabaseLimits::default();for phase in[SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::EncodeNative]{let mut reached=false;let mut callback=|event:SqliteSnapshotProgress|if event.phase==phase&&event.total>=2048&&event.completed>=256&&event.completed<event.total{reached=true;false}else{true};let mut control=SqliteSnapshotControl::new(&mut callback,limits);let rejected=if phase==SqliteSnapshotPhase::ProjectSnapshot{expected.to_sqlite_database(&mut control).is_err()}else{expected.encode_sqlite_snapshot_native(SnapshotEncoding::Text,&mut control).is_err()};assert!(rejected,"{phase:?}");assert!(reached,"{phase:?}")}
}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_workflow_imperative_registration_routes_actual_queryable_files(){
 let codec=store::ArtifactCodec::bare::<WorkflowSnapshot,WorkflowMutation>(S_WORKFLOW_SCHEMA);store::io::register_native_document_codec(semio_framework_artifact_reference::Dialect{artifact_kind:"os.workflow",standard:semio_framework_artifact_reference::StandardId("1"),subset:semio_framework_artifact_reference::SubsetId("*")},codec).unwrap();let expected=source();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let bytes=store::io::io_mechanism::io_export_sqlite_snapshot(&dialect(),&expected,encoding,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;assert!(bytes.starts_with(b"SQLite format 3\0"));assert_eq!(store::io::io_mechanism::io_import_sqlite_snapshot::<WorkflowSnapshot>(&dialect(),&bytes,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value,expected);}
}

#[test]
fn sqlite_snapshot_workflow_intrinsic_contract_full_native_and_sqlite_branches(){
 let cases:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🎞️wire/🔣️.json")).unwrap();
 for schema in cases["schemas"].as_array().unwrap(){
  let mut expected=source();expected.graph.edges[1].contract.wire=crate::MediaWireFormat::Intrinsic{schema:schema.as_str().unwrap().to_owned()};
  assert_eq!(restore(&database(&expected)),expected);
  for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
   let codec=store::ArtifactCodec::bare::<WorkflowSnapshot,WorkflowMutation>(S_WORKFLOW_SCHEMA);let owner=codec.snapshot_sqlite.unwrap();
   let source=payload(&expected,encoding);
   let db=(owner.export)(&codec.schema,&dialect(),&source,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
   let result=(owner.import)(&codec.schema,&dialect(),db,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
   let actual=WorkflowSnapshot::decode_sqlite_snapshot_native(&result,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
   assert_eq!(actual,expected);
  }
 }
}

fn cell_laws()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/📏️semantic-cells/🔣️.json")).unwrap()}
#[test]
fn sqlite_snapshot_workflow_complete_semantic_cells_are_exact_for_every_ieee_branch(){
 let law=cell_laws();for case in law["cases"].as_array().unwrap(){let mut expected=source();if case["name"]!="base"{let bits=u64::from_str_radix(case["name"].as_str().unwrap(),16).unwrap();let number=f64::from_bits(bits);for node in&mut expected.graph.nodes{node.x=number;node.y=number;node.width=number;node.height=number;}for parameter in&mut expected.parameters{if let crate::WorkflowParameter::Numeric{value,min,max,step,..}=parameter{*value=number;*min=Some(number);*max=Some(number);*step=Some(number)}}}
 let bytes=usize::try_from(case["bytes"].as_u64().unwrap()).unwrap();let defaults=SqliteDatabaseLimits::default();let d=database(&expected);assert_eq!(d.tables.len(),usize::try_from(law["tables"].as_u64().unwrap()).unwrap());assert_eq!(d.tables.iter().map(|table|table.rows.len()).sum::<usize>(),usize::try_from(law["rows"].as_u64().unwrap()).unwrap());
 for allowance in[bytes,bytes-1]{let limits=SqliteDatabaseLimits{max_value_bytes:allowance,..defaults};assert_eq!(expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_ok(),allowance==bytes,"project {}",case["name"]);assert_eq!(WorkflowSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_ok(),allowance==bytes,"reconstruct {}",case["name"]);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{assert_eq!(expected.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_ok(),allowance==bytes,"encode {}",case["name"]);assert_eq!(WorkflowSnapshot::decode_sqlite_snapshot_native(&payload(&expected,encoding),&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_ok(),allowance==bytes,"decode {}",case["name"]);}}
 println!("[DEBUG] Workflow full semantic native frontier case={} complete_bytes={bytes}",case["name"]);
 }
}
#[path="./\u{1f4b0}\u{FE0F}backing/\u{1f980}\u{FE0F}.rs"]mod allocation;
#[test]
fn sqlite_snapshot_workflow_reconstruction_pays_actual_system_requests_cumulatively(){
 let law=cell_laws();let backing=&law["nativeBacking"];assert_eq!(backing["requestIncludesReallocFullSize"],true);let maximum=usize::try_from(backing["maximumBytes"].as_u64().unwrap()).unwrap();let expected=source();let database=database(&expected);let defaults=SqliteDatabaseLimits{max_allocation_bytes:maximum,..SqliteDatabaseLimits::default()};let mut accept=|_|true;let mut control=SqliteSnapshotControl::new(&mut accept,defaults);
 let(result,requested)=allocation::observe(||WorkflowSnapshot::from_sqlite_database(&database,&mut control));assert_eq!(result.unwrap(),expected);let admitted=maximum-control.allocation_remaining_bytes();println!("[DEBUG] Workflow actual system backing requests={requested} caller_admitted={admitted} semantic_cells_separate=true");assert!(admitted>0,"real Workflow indexes and typed allocations must settle in the caller ledger");assert_eq!(admitted,requested,"./every complete source/typed backing request must be admitted");
 for allowance in[admitted,admitted-1,0,1]{let limits=SqliteDatabaseLimits{max_allocation_bytes:allowance,..defaults};let mut accept=|_|true;let mut control=SqliteSnapshotControl::new(&mut accept,limits);let(result,requested)=allocation::observe(||WorkflowSnapshot::from_sqlite_database(&database,&mut control));if allowance==admitted{assert_eq!(result.unwrap(),expected);assert_eq!(requested,admitted);assert_eq!(control.allocation_remaining_bytes(),0);}else{assert_eq!(result.unwrap_err().kind,semio_framework_value::ValueRefusalKind::OwnershipLimit);assert!(control.allocation_remaining_bytes()<=allowance);}}
 let repetitions=usize::try_from(backing["repeatedOwnerships"].as_u64().unwrap()).unwrap();assert_eq!(repetitions,2);let total=admitted.checked_mul(repetitions).unwrap();let mut accept=|_|true;let mut control=SqliteSnapshotControl::new(&mut accept,SqliteDatabaseLimits{max_allocation_bytes:total,..defaults});for _ in 0..repetitions{let(result,requested)=allocation::observe(||WorkflowSnapshot::from_sqlite_database(&database,&mut control));assert_eq!(result.unwrap(),expected);assert_eq!(requested,admitted);}assert_eq!(control.allocation_remaining_bytes(),0);assert_eq!(WorkflowSnapshot::from_sqlite_database(&database,&mut control).unwrap_err().kind,semio_framework_value::ValueRefusalKind::OwnershipLimit);
}
